"use strict";
// Access keys of the web page (bin/bridge-web.js). Node built-in modules only.
// A key is PREFIX-<32 random base62 characters>. The PREFIX (4 letters or digits) is chosen by the person,
// the random part is generated by the platform. Only a HASH (scrypt + salt) is stored, in a file with mode 600:
//   { keys: [{ id, prefix, label, alg, N, r, p, salt, hash, created, createdBy, revoked, lastLogin }],
//     setup: [{ id, th (sha256 of the link token), exp, prefix, label, used }] }
// A setup link works once and expires after 10 minutes.
const fs = require("node:fs");
const path = require("node:path");
const os = require("node:os");
const crypto = require("node:crypto");

const B62 = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";
const PREFIX_RE = /^[A-Za-z0-9]{4}$/;
const LABEL_RE = /^[A-Za-z0-9]{1,12}$/;
const KEY_RE = /^([A-Za-z0-9]{4})-([A-Za-z0-9]{32})$/;
const TOKEN_RE = /^[A-Za-z0-9]{40}$/;
const SCRYPT = { N: 16384, r: 8, p: 1 };
const SETUP_TTL_MS = 10 * 60 * 1000;

class KeyError extends Error { constructor(code, message) { super(message); this.code = code; } }

// The private folder of the web page: keys and session secret. Never inside the bridge folder (agents read it).
function webDir() {
  const d = path.resolve(process.env.BRIDGE_WEB_DIR || path.join(os.homedir(), ".config", "bridge", "web"));
  if (!fs.existsSync(d)) fs.mkdirSync(d, { recursive: true, mode: 0o700 });
  fs.chmodSync(d, 0o700);
  return d;
}

function rand62(n) {
  let s = "";
  while (s.length < n) for (const b of crypto.randomBytes(n * 2)) if (b < 248 && s.length < n) s += B62[b % 62]; // no modulo bias
  return s;
}
const sha256 = (s) => crypto.createHash("sha256").update(s).digest("hex");

function open(file) {
  const FILE = file || path.join(webDir(), "keys.json");
  let cache = { mtime: -1, data: null };
  function load() {
    let st;
    try { st = fs.statSync(FILE); } catch (_) { return { keys: [], setup: [] }; }
    if (cache.data && cache.mtime === st.mtimeMs) return cache.data;
    const d = JSON.parse(fs.readFileSync(FILE, "utf8"));
    d.keys = d.keys || []; d.setup = d.setup || [];
    cache = { mtime: st.mtimeMs, data: d };
    return d;
  }
  function save(d) {
    const now = Date.now();
    d.setup = (d.setup || []).filter((s) => !s.used && Date.parse(s.exp) > now); // used or expired links are removed
    const tmp = path.join(path.dirname(FILE), `.tmp-${path.basename(FILE)}-${process.pid}-${crypto.randomBytes(3).toString("hex")}`);
    fs.writeFileSync(tmp, JSON.stringify(d, null, 1) + "\n", { mode: 0o600, flag: "wx" });
    fs.renameSync(tmp, FILE);
    fs.chmodSync(FILE, 0o600);
    cache = { mtime: -1, data: null };
  }
  function update(fn) { const d = JSON.parse(JSON.stringify(load())); const r = fn(d); save(d); return r; }

  function checkPrefix(p) {
    if (!PREFIX_RE.test(String(p || ""))) throw new KeyError("prefix", "invalid prefix: exactly 4 letters or digits");
    return String(p).toUpperCase();
  }
  function checkLabel(l, prefix) {
    const v = l === undefined || l === null || l === "" ? prefix : String(l);
    if (!LABEL_RE.test(v)) throw new KeyError("label", "invalid tag: 1 to 12 letters or digits");
    return v.toUpperCase();
  }
  const pub = (k) => ({ id: k.id, prefix: k.prefix, label: k.label, created: k.created, createdBy: k.createdBy, revoked: k.revoked, lastLogin: k.lastLogin });
  const scryptP = (pw, salt, k = SCRYPT) => new Promise((res, rej) => crypto.scrypt(pw, salt, 32, { N: k.N, r: k.r, p: k.p }, (e, b) => (e ? rej(e) : res(b))));

  // Generates a key, stores its hash, returns the key IN CLEAR (to show once, never stored).
  function createKey({ prefix, label, by }) {
    const P = checkPrefix(prefix), L = checkLabel(label, P);
    const key = `${P}-${rand62(32)}`;
    const salt = crypto.randomBytes(16);
    const hash = crypto.scryptSync(key, salt, 32, SCRYPT);
    const id = crypto.randomBytes(4).toString("hex");
    update((d) => {
      d.keys.push({ id, prefix: P, label: L, alg: "scrypt", ...SCRYPT, salt: salt.toString("hex"), hash: hash.toString("hex"),
        created: new Date().toISOString(), createdBy: String(by || "server").slice(0, 40), revoked: null, lastLogin: null });
    });
    return { id, prefix: P, label: L, key };
  }
  // Checks a typed key. Returns the record (without hash) or null. Async so the server is not blocked.
  async function verify(input) {
    const m = KEY_RE.exec(String(input || "").normalize("NFC").trim());
    if (!m) { await scryptP("x", "y"); return null; } // same cost for a malformed key
    const P = m[1].toUpperCase(), norm = `${P}-${m[2]}`;
    const cands = load().keys.filter((k) => k.prefix === P && !k.revoked);
    if (!cands.length) { await scryptP("x", "y"); return null; }
    for (const k of cands) {
      const dk = await scryptP(norm, Buffer.from(k.salt, "hex"), k);
      if (crypto.timingSafeEqual(dk, Buffer.from(k.hash, "hex"))) {
        try { update((d) => { const x = d.keys.find((y) => y.id === k.id); if (x) x.lastLogin = new Date().toISOString(); }); } catch (_) { /* read-only is fine */ }
        return pub(k);
      }
    }
    return null;
  }
  function active(id) { const k = load().keys.find((x) => x.id === id && !x.revoked); return k ? pub(k) : null; }
  function list() { return load().keys.map(pub); }
  function revoke(id) {
    return update((d) => {
      const k = d.keys.find((x) => x.id === id);
      if (!k) throw new KeyError("notfound", "key not found");
      if (k.revoked) return pub(k);
      if (d.keys.filter((x) => !x.revoked).length <= 1) throw new KeyError("lastkey", "refused: this is the last active key (create another key first)");
      k.revoked = new Date().toISOString();
      return pub(k);
    });
  }
  // One-time setup link (10 min). Returns the token IN CLEAR (only its sha256 is stored).
  function createSetup({ prefix, label } = {}) {
    const P = prefix ? checkPrefix(prefix) : null;
    const L = label ? checkLabel(label, P || "X") : null;
    const token = rand62(40);
    update((d) => { d.setup.push({ id: crypto.randomBytes(4).toString("hex"), th: sha256(token), exp: new Date(Date.now() + SETUP_TTL_MS).toISOString(), prefix: P, label: L, used: null }); });
    return { token, minutes: SETUP_TTL_MS / 60000 };
  }
  function findSetup(token) {
    if (!TOKEN_RE.test(String(token || ""))) return null;
    const th = sha256(token);
    const s = load().setup.find((x) => crypto.timingSafeEqual(Buffer.from(x.th, "hex"), Buffer.from(th, "hex")));
    if (!s || s.used || Date.parse(s.exp) <= Date.now()) return null;
    return { prefix: s.prefix, label: s.label, exp: s.exp, th };
  }
  // Consumes the link (once), then creates the key.
  function useSetup(token, { prefix, label }) {
    const s = findSetup(token);
    if (!s) throw new KeyError("link", "link invalid, already used or expired");
    const P = checkPrefix(s.prefix || prefix), L = checkLabel(s.label || label, P);
    update((d) => { const x = d.setup.find((y) => y.th === s.th); if (!x || x.used) throw new KeyError("link", "link already used"); x.used = new Date().toISOString(); });
    return createKey({ prefix: P, label: L, by: "setup link" });
  }
  return { FILE, createKey, verify, active, list, revoke, createSetup, findSetup, useSetup };
}

// Session signing secret: generated on first start, mode 600, in the private web folder.
function sessionSecret(file) {
  const F = file || path.join(webDir(), "session-secret");
  try {
    const s = fs.readFileSync(F, "utf8").trim();
    if (!/^[0-9a-f]{64}$/.test(s)) throw new KeyError("secret", "session secret unreadable: delete it to regenerate (all sessions end)");
    return Buffer.from(s, "hex");
  } catch (e) {
    if (e.code !== "ENOENT") throw e;
    const s = crypto.randomBytes(32).toString("hex");
    fs.writeFileSync(F, s + "\n", { mode: 0o600, flag: "wx" });
    return Buffer.from(s, "hex");
  }
}

module.exports = { open, sessionSecret, webDir, rand62, KeyError, PREFIX_RE, LABEL_RE, KEY_RE, TOKEN_RE, SETUP_TTL_MS };
